<?php
namespace App\Services;
use GuzzleHttp\Client;use RuntimeException;
class GovUkSponsorRegisterClient{private readonly Client $http;public function __construct(?Client $http=null){$this->http=$http ?? new Client(['timeout'=>60,'headers'=>['User-Agent'=>'UK Sponsor Licence Checker']]);}public function latestCsvUrl():string{$url=config('services.govuk.sponsor_register_url');$html=(string)$this->http->get($url)->getBody();preg_match_all('/href=["\']([^"\']+\.csv[^"\']*)["\']/i',$html,$m);if(empty($m[1])){throw new RuntimeException('No CSV link found on GOV.UK sponsor register page.');}$csv=end($m[1]);return str_starts_with($csv,'http')?$csv:'https://www.gov.uk'.$csv;}public function downloadCsv(string $url):string{$body=(string)$this->http->get($url)->getBody();if(strlen($body)<100||!str_contains(strtolower($body),'organisation')){throw new RuntimeException('Downloaded CSV failed validation.');}return mb_convert_encoding($body,'UTF-8','UTF-8, ISO-8859-1, Windows-1252');}}
